function replacement(sentence,answer,wrong,clue,rule){
 const target=sentence.match(/\[([^\]]+)\]/)[1];
 usage.push(item(sentence,answer,wrong,clue,rule,'Contextual replacement: meaning, form and collocation',sentence.replace('['+target+']',answer==='No replacement required'?target:answer),'word replacement'));
 usage.at(-1).instructions='Replace the word in square brackets, or select No replacement required. Preserve the sentence’s intended meaning.';
}
