function usages(term,sentences,valid,reasons,models,incorrect=false){
 const labels=['I','II','III'];const wanted=labels.filter((_,i)=>incorrect?!valid[i]:valid[i]);
 const lbl=xs=>xs.length===3?'I, II and III':xs.length?xs.join(' and ')+' only':'None';
 const answer=lbl(wanted),pool=[['I'],['II'],['III'],['I','II'],['I','III'],['II','III'],['I','II','III'],[]].map(lbl).filter(x=>x!==answer);
 const q=item(`In which sentence(s) is “${term}” used ${incorrect?'INCORRECTLY':'correctly'}?`,answer,pool.slice(0,4).map(x=>[x,'Evaluate all three uses; the complete required combination is '+answer+'.']),
 `Check the meaning, grammatical role and usual partners of ${term} in each sentence.`,'A familiar word can have several valid senses; judge each actual construction.',incorrect?'Direction: select incorrect USES':'Direction: select correct USES',models.join(' '),'contextual usage combination');
 q.candidates=sentences.map((text,i)=>({label:labels[i],text,valid:valid[i],reason:reasons[i]}));q.vocabulary=[term];
 q.instructions=`Select the complete combination of ${incorrect?'incorrect':'correct'} uses. In the explanation, valid means the word is used correctly.`;
 usage.push(q);
}
