function swap(template,words,corrupt,skill='word swap'){
 const labels=['A','B','C','D'],pairs=[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]];
 const changed=words.map((_,i)=>corrupt[i]);
 function run(p){const result=[...changed];for(const [a,b]of p)[result[a],result[b]]=[result[b],result[a]];return result;}
 function render(w,marked=false){return template.replace(/\{([A-D])\}/g,(_,l)=>w[labels.indexOf(l)]+(marked?` (${l})`:''));}
 const name=p=>p.length?p.map(([a,b])=>labels[a]+'–'+labels[b]).join(' and ')+(p.length===1?' only':''):'No interchange required';
 const all=[...pairs.map(p=>[p]),[[0,1],[2,3]],[[0,2],[1,3]],[[0,3],[1,2]],[]];
 const solutions=all.filter(p=>run(p).every((x,i)=>x===words[i]));if(solutions.length!==1)throw Error('Swap needs exactly one mechanical solution: '+template);
 const correct=solutions[0];
 const pool=all.filter(p=>p!==correct&&(correct.length===2?p.length===2||p.length===0||name(p)==='A–B only':p.length<=1));
 const options=correct.length===1?[...pool.filter(p=>p.length).slice(0,3),all.at(-1)]:pool.slice(0,4);
 const reason=p=>{const r=run(p);return labels.filter((_,i)=>r[i]!==words[i]).map(l=>`Position ${l} needs “${words[labels.indexOf(l)]}”, not “${r[labels.indexOf(l)]}”`).join('; ')+'. Re-read all four positions.';};
 usage.push(item(render(changed,true),name(correct),options.map(p=>[name(p),reason(p)]),
 words.map((w,i)=>`${labels[i]} belongs in “${template.split('{'+labels[i]+'}')[0].split(/[.;]/).at(-1).trim().split(' ').slice(-4).join(' ')} ${w}”`).join('; '),
 'Move only the labelled words. Preserve the unlabelled words and verify all resulting meanings and collocations.',correct.length===0?'Direction: all four words already fit':'Direction: restore the intended words to every labelled position',render(words),skill));
 usage.at(-1).instructions='Only the four labelled words may be interchanged. Choose the operation that makes every position fit. Use No interchange required if they already fit.';
}
