const existing=read('vocabulary.json');
const selectedExisting=['cursory','exhaustive','explicit','refute','redress','deter','disburse','stipulated','lucrative'];
const definitions={
 cursory:['quick and superficial rather than thorough','a cursory inspection / a cursory glance','The cursory inspection missed a discrepancy that a later detailed audit identified.',['cursorily']],
 exhaustive:['thorough and complete, covering all relevant details','an exhaustive review / an exhaustive investigation','The exhaustive review covered every branch and every disputed transaction.',[]],
 explicit:['clearly and directly stated','explicit instructions / explicit consent','The notice gave explicit instructions about the documents needed for verification.',['explicitly']],
 refute:['prove a statement or claim to be wrong','refute a claim / refute an allegation','The dated receipt helped refute the claim that the payment had never been made.',['refuted','refuting']],
 redress:['remedy or compensation for a wrong or loss; to remedy or compensate for it','seek redress / redress a grievance','The borrower sought redress after an incorrect debit remained unresolved.',['redressed','redressing']],
 deter:['discourage someone from doing something, especially by making consequences seem unpleasant','deter fraud / deter someone from doing something','Additional identity checks can deter fraud without delaying genuine applications.',['deterred','deterring','deterrent']],
 disburse:['pay out money, especially from a fund','disburse funds / disburse a loan','The bank will disburse the approved funds after the final checks.',['disbursed','disbursing','disbursement']],
 stipulated:['specified or required as part of an agreement or instruction','within the stipulated period / a stipulated condition','The borrower submitted the documents within the stipulated period.',['stipulate','stipulation']],
 lucrative:['producing a substantial profit or income','a lucrative business / a lucrative contract','The contract looked lucrative, but the bank still examined the risks before financing it.',[]]
};
function vocabCandidate(term){const [meaning,collocations,readingExample,forms]=definitions[term];const old=existing.find(v=>v.term===term);return {term,meaning:old?.meaning||meaning,collocations:[collocations],forms,important:true,readingExample};}
function chapter(id,title,questions,titles){
 if(questions.length!==40)throw Error(id+' has '+questions.length+' questions, expected 40.');
 const candidates=selectedExisting.filter(term=>questions.some(q=>hasTerm(JSON.stringify(q),term)||(definitions[term][3]||[]).some(f=>hasTerm(JSON.stringify(q),f)))).map(vocabCandidate);
 const vocab=existing.map(v=>v.term).filter(t=>!t.includes('+'));
 const c={id,title,description:'40 new original practice questions: warm-ups, mains-style application and harder combinations. Inspired by supplied formats; these are not unchanged previous-year questions, and level labels are approximate.',source:{kind:'original-format-practice',formatReferences:refs[id],note:'Source references describe formats only; all sentences, options and explanations in this chapter are newly authored.'},vocabularyCandidates:candidates,packs:[]};
 for(let i=0;i<8;i++){
  const pack={id:(id==='grammar'?'G':id==='fillers'?'F':'W')+String(i+1).padStart(2,'0'),title:titles[i],level:i<2?'Warm-up':i<6?'Mains-style':'Higher practice',questions:questions.slice(i*5,i*5+5)};
  pack.questions.forEach((q,j)=>{q.id=id+'/'+pack.id+'-Q'+(j+1);q.source={kind:'original-format-practice',formatReferences:refs[id]};q.vocabulary=[...new Set([...(q.vocabulary||[]),...vocab.filter(t=>hasTerm([q.prompt,q.explanation.model].join(' '),t))])];});
  c.packs.push(pack);
 }
 write('chapters/'+id+'.json',c);
}
chapter('grammar','Errors & correction',grammar,['Repair the core construction','Retain correct sentences','Complements and inversion','Find the real subject','Word order and genuine no-error','Time, parallelism and paired structures','Judge every statement','Harder combinations and direction checks']);
chapter('fillers','Contextual fillers',fillers,['Direction, collocation and context','Clarity, coverage and financial meaning','Evidence limits and precise meaning','Double fillers: check both blanks','Double fillers: opposing meanings','Same word: two roles, two checks','Same word: no forced answer','Phrases, prerequisites and contrast']);
chapter('word-usage','Word usage & swaps',usage,['Contextual replacement','Retain correct wording','Usage: check all three sentences','Multiple senses and incorrect-use directions','Restore a single pair','Check every labelled position','Two swaps: neither pair is enough','No interchange is a real answer']);
const registry=read('registry.json');for(const id of ['grammar','fillers','word-usage']){if(registry.some(r=>r.id===id))throw Error('Chapter already registered: '+id);registry.push({id,file:id+'.json'});}write('registry.json',registry);
console.log('Added 3 chapters, 24 sets and 120 authored questions. Run vocabulary sync, validation and build next.');
